138	        return jdbc.queryForObject("SELECT due_floor FROM sheet WHERE id = ?", BigDecimal.class, sheetId);
139	    }
140	
141	    public void setFloor(String sheetId, BigDecimal floor) {
142	        sheets.today(sheetId);
143	        jdbc.update("UPDATE sheet SET due_floor = ? WHERE id = ?", floor, sheetId);
144	    }
145	
146	    /** The sheet's terms in days: a claim's due-by is its date plus them. */
147	    public int terms(String sheetId) {
148	        sheets.today(sheetId); // the sheet's row holds the terms
149	        return jdbc.queryForObject("SELECT terms_days FROM sheet WHERE id = ?", Integer.class, sheetId);
150	    }
151	
152	    public void setTerms(String sheetId, int days) {
153	        sheets.today(sheetId);
154	        jdbc.update("UPDATE sheet SET terms_days = ? WHERE id = ?", days, sheetId);
155	    }
156	
157	    /** The sheet's late percent: an overdue claim gains it of its figure for every full 30 days overdue. */
158	    public BigDecimal latePct(String sheetId) {
159	        sheets.today(sheetId); // the sheet's row holds the late percent
160	        return jdbc.queryForObject("SELECT late_pct FROM sheet WHERE id = ?", BigDecimal.class, sheetId);
161	    }
162	
163	    public void setLatePct(String sheetId, BigDecimal pct) {
164	        sheets.today(sheetId);
165	        jdbc.update("UPDATE sheet SET late_pct = ? WHERE id = ?", pct, sheetId);
166	    }
167	
168	    /** The sheet's policy date as set; null when blank. */
169	    public LocalDate policyDateSet(String sheetId) {
170	        sheets.today(sheetId); // the sheet's row holds the policy date
171	        Date date = jdbc.queryForObject("SELECT policy_date FROM sheet WHERE id = ?", Date.class, sheetId);
172	        return date == null ? null : date.toLocalDate();
173	    }
174	
175	    /** The sheet's policy date: a claim dated before it rounds half up, on or after it half to even.
176	     *  When blank it is the sheet's today. */
177	    public LocalDate policyDate(String sheetId) {
178	        LocalDate set = policyDateSet(sheetId);
179	        return set != null ? set : sheets.today(sheetId);
180	    }
181	
182	    public void setPolicyDate(String sheetId, LocalDate date) {
183	        sheets.today(sheetId);
184	        jdbc.update("UPDATE sheet SET policy_date = ? WHERE id = ?", date == null ? null : Date.valueOf(date), sheetId);
185	    }
186	
187	    /** The role the user name holds on the sheet; a clerk unless set otherwise. */
188	    public String role(String sheetId, String user) {
189	        List<String> found = jdbc.query("SELECT role FROM sheet_role WHERE sheet_id = ? AND user_name = ?",
190	                (rs, i) -> rs.getString(1), sheetId, user == null ? "" : user.trim());
191	        return found.isEmpty() ? CLERK : found.get(0);
