194	    public void setRole(String sheetId, String user, String role) {
195	        jdbc.update("MERGE INTO sheet_role (sheet_id, user_name, role) KEY (sheet_id, user_name) VALUES (?, ?, ?)",
196	                sheetId, user, role);
197	    }
198	
199	    /** The sheet's settings as shown: the clerk limit ("" for none), the floor, the terms, the late percent, the policy date ("" for blank) and every role set, by user name. */
200	    public SettingsResponse load(String sheetId) {
201	        BigDecimal limit = clerkLimit(sheetId);
202	        LocalDate policy = policyDateSet(sheetId);
203	        List<RoleResponse> roles = jdbc.query(
204	                "SELECT user_name, role FROM sheet_role WHERE sheet_id = ? ORDER BY user_name",
205	                (rs, i) -> new RoleResponse(rs.getString(1), rs.getString(2)), sheetId);
206	        return new SettingsResponse(limit == null ? "" : limit.setScale(2).toPlainString(),
207	                floor(sheetId).setScale(2).toPlainString(), String.valueOf(terms(sheetId)),
208	                latePct(sheetId).setScale(2).toPlainString(), policy == null ? "" : policy.toString(), roles);
