246	public class ValidateSetting {
247	
248	    public static final String CLERK_LIMIT = "clerk-limit";
249	
250	    public static final String FLOOR = "floor";
251	
252	    public static final String TERMS = "terms";
253	
254	    public static final String LATE_PCT = "late-pct";
255	
256	    public static final String POLICY_DATE = "policy-date";
257	
258	    /** A number of days: 0 or more, whole. */
259	    private static final Pattern DAYS = Pattern.compile("\\d{1,4}");
260	
261	    /** A percent: 0 or more, with at most two decimals. */
262	    private static final Pattern PERCENT = Pattern.compile("\\d{1,3}(\\.\\d{1,2})?");
263	
264	    /** An amount: 0 or more, with at most two decimals. */
265	    private static final Pattern AMOUNT = Pattern.compile("\\d{1,10}(\\.\\d{1,2})?");
266	
267	    public void validate(@RequestBody SettingRequest request, Out<ValidSetting> body) throws InvalidSettingException {
268	        String key = request.key() == null ? "" : request.key().trim();
269	        if (!CLERK_LIMIT.equals(key) && !FLOOR.equals(key) && !TERMS.equals(key) && !LATE_PCT.equals(key)
270	                && !POLICY_DATE.equals(key)) {
271	            throw new InvalidSettingException("No such setting: " + key);
272	        }
273	        String raw = request.value() == null ? "" : request.value().trim();
274	        if (POLICY_DATE.equals(key)) {
275	            if (raw.isEmpty()) {
276	                body.set(new ValidSetting(key, null, request.user(), null)); // blank: the sheet's today
277	                return;
278	            }
279	            try {
280	                body.set(new ValidSetting(key, null, request.user(), LocalDate.parse(raw)));
281	            } catch (DateTimeParseException e) {
282	                throw new InvalidSettingException("The policy date must be a date (YYYY-MM-DD), or blank for the sheet's today");
283	            }
284	            return;
285	        }
286	        if (TERMS.equals(key)) {
287	            if (!DAYS.matcher(raw).matches()) {
288	                throw new InvalidSettingException("The terms must be a whole number of days, 0 or more");
289	            }
290	            body.set(new ValidSetting(key, new BigDecimal(Integer.parseInt(raw)), request.user()));
291	            return;
292	        }
293	        if (LATE_PCT.equals(key)) {
294	            if (!PERCENT.matcher(raw).matches()) {
295	                throw new InvalidSettingException("The late percent must be a percent of 0.00 or more with at most two decimals");
296	            }
297	            body.set(new ValidSetting(key, new BigDecimal(raw).setScale(2), request.user()));
298	            return;
299	        }
300	        if (FLOOR.equals(key)) {
301	            if (!AMOUNT.matcher(raw).matches()) {
302	                throw new InvalidSettingException("The floor must be an amount of 0.00 or more with at most two decimals");
303	            }
304	            body.set(new ValidSetting(key, new BigDecimal(raw).setScale(2), request.user()));
305	            return;
306	        }
307	        if (raw.isEmpty()) {
308	            body.set(new ValidSetting(key, null, request.user())); // blank: no limit
309	            return;
310	        }
311	        if (!AMOUNT.matcher(raw).matches()) {
312	            throw new InvalidSettingException("The clerk limit must be an amount of 0.00 or more with at most two decimals");
313	        }
314	        body.set(new ValidSetting(key, new BigDecimal(raw).setScale(2), request.user()));
315	    }
316	}
