347	public class ApplyClaimStatus {
348	    public void apply(@Val ValidClaimStatus request, @Val Claim claim, Sheets sheets, People people,
349	            Rates rates, Periods periods, Settings settings, Out<ClaimNumber> number)
350	            throws ClaimStatusRefusedException {
351	        RoundingMode rounding = Rounding.of(claim, settings.policyDate(claim.getSheetId()));
352	        if (periods.isClosed(claim.getSheetId(), claim.getDate())) {
353	            throw new ClaimStatusRefusedException("No claim dated inside a closed period can change status");
354	        }
355	        if (!claim.getStatus().canBecome(request.target())) {
356	            throw new ClaimStatusRefusedException(claim.getStatus(), request.target());
357	        }
358	        if (request.target() == ClaimStatus.SETTLED && claim.getOpenedBy() != null
359	                && claim.getOpenedBy().equals(request.user())) {
360	            // Four eyes: the user who opened a claim cannot settle it.
361	            throw new ClaimStatusRefusedException("The user who opened a claim cannot settle it");
362	        }
363	        if (request.target() == ClaimStatus.SETTLED
364	                && !Settings.STEWARD.equals(settings.role(claim.getSheetId(), request.user()))) {
365	            // A clerk settles only within the sheet's clerk limit, judged on the claim's due as shown;
366	            // a due of n/a is within any limit.
367	            BigDecimal limit = settings.clerkLimit(claim.getSheetId());
368	            String grade = people.find(claim.getSheetId(), claim.getPersonId()).gradeOn(claim.getDate());
369	            BigDecimal fixed = ClaimResponse.fixedDue(claim);
370	            BigDecimal figure = fixed != null || claim.isStated() ? fixed
371	                    : Rates.due(claim.getAmount(), rates.find(claim.getSheetId(), grade, claim.getDate()),
372	                    settings.floor(claim.getSheetId()), rounding);
373	            BigDecimal due = LateCharge.withCharge(claim, figure, settings.latePct(claim.getSheetId()),
374	                    settings.terms(claim.getSheetId()), sheets.today(claim.getSheetId()), rounding);
375	            if (limit != null && due != null && due.compareTo(limit) > 0) {
376	                throw new ClaimStatusRefusedException("A clerk cannot settle a claim whose due is above the clerk limit");
377	            }
378	        }
379	        if (request.target() == ClaimStatus.OPEN) {
380	            claim.setNumber(sheets.nextClaimNumber(claim.getSheetId()));
381	            claim.setOpenedBy(request.user());
382	        }
383	        // A voided claim keeps its number; numbers are never reused.
384	        number.set(new ClaimNumber(claim.getNumber()));
385	        if (request.target() == ClaimStatus.SETTLED) {
386	            // Settling fixes the due: the figure a statement bound it to, else its amount (raised to the floor)
387	            // at the rate in force on the claim's date, with its late charge as of today frozen in; with no
388	            // figure it stays live (n/a until a rate is set).
389	            String grade = people.find(claim.getSheetId(), claim.getPersonId()).gradeOn(claim.getDate());
390	            BigDecimal figure = claim.isStated() && claim.getStatedDue() != null ? claim.getStatedDue()
391	                    : Rates.due(claim.getAmount(), rates.find(claim.getSheetId(), grade, claim.getDate()),
392	                    settings.floor(claim.getSheetId()), rounding);
393	            claim.setSettledDue(LateCharge.withCharge(claim, figure, settings.latePct(claim.getSheetId()),
394	                    settings.terms(claim.getSheetId()), sheets.today(claim.getSheetId()), rounding));
395	        }
396	        claim.setStatus(request.target());
397	    }
398	}
