415	/**
416	 * Opens the selected claims in list order (people in the order they were added, newest claim first
417	 * within a person), numbering each as it opens and auditing it as a single open would be. A selected
418	 * claim that cannot be opened (not DRAFT, or dated inside a closed period) is left as it is and counted
419	 * as refused; so is a selected id that is not a claim on the sheet.
420	 */
421	public class BulkOpenClaims {
422	    public void open(@PathVariable("sheetId") String sheetId, @RequestBody BulkOpenRequest request,
423	            Claims claims, People people, Periods periods, Sheets sheets, Rollup rollup, Audit audit,
424	            ObjectResponse<BulkOpenResponse> response) {
425	        Set<String> selected = new HashSet<>(request.claimIds() == null ? List.of() : request.claimIds());
426	        List<Claim> all = claims.list(sheetId);
427	        int opened = 0;
428	        for (Person person : people.list(sheetId)) {
429	            for (Claim claim : all) {
430	                if (claim.getPersonId() != person.getId() || !selected.contains(String.valueOf(claim.getId()))) {
431	                    continue;
432	                }
433	                if (!claim.getStatus().canBecome(ClaimStatus.OPEN)
434	                        || periods.isClosed(sheetId, claim.getDate())) {
435	                    continue;
436	                }
437	                RollupFigures before = rollup.figures(sheetId);
438	                claim.setNumber(sheets.nextClaimNumber(sheetId));
439	                claim.setOpenedBy(request.user());
440	                claim.setStatus(ClaimStatus.OPEN);
441	                claims.save(claim);
442	                audit.recordOnCommit(ClaimAudit.line("CLAIM_OPENED", request.user(), person, claim, claim.getNumber()));
443	                rollup.recordChanges(sheetId, request.user(), before);
444	                opened++;
445	            }
446	        }
447	        response.send(new BulkOpenResponse(opened, selected.size() - opened));
448	    }
449	}
